CREATE DATABASE IF NOT EXISTS nesere_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nesere_db;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') DEFAULT 'customer',status TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services(service_id INT AUTO_INCREMENT PRIMARY KEY,service_name VARCHAR(150) NOT NULL,description TEXT,image VARCHAR(255),price DECIMAL(12,2) DEFAULT 0,status TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_packages(package_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description TEXT,price DECIMAL(12,2) NOT NULL,duration VARCHAR(100),features TEXT,status TINYINT DEFAULT 1);
CREATE TABLE service_requests(request_id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,service_id INT NOT NULL,project_title VARCHAR(180) NOT NULL,description TEXT,location VARCHAR(180),preferred_date DATE,budget DECIMAL(12,2),attachment VARCHAR(255),status ENUM('Pending','Reviewed','Quotation Sent','Approved','In Progress','Completed','Rejected') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES services(service_id));
CREATE TABLE quotations(quotation_id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,details TEXT,valid_until DATE,status ENUM('Pending','Accepted','Rejected') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES service_requests(request_id) ON DELETE CASCADE);
CREATE TABLE projects(project_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,category VARCHAR(100),image VARCHAR(255),video_url VARCHAR(255),status ENUM('Active','Completed') DEFAULT 'Completed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews(review_id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT,project_id INT,rating TINYINT NOT NULL,comment TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(user_id) ON DELETE SET NULL);
CREATE TABLE messages(message_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,subject VARCHAR(180),message TEXT NOT NULL,is_admin TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE notifications(notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message TEXT NOT NULL,is_read TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE social_media_links(id INT AUTO_INCREMENT PRIMARY KEY,platform VARCHAR(50),url VARCHAR(255));
